        l, r = 0, len(nums) - 1

        while l < r:
            m = (l + r) // 2
            if nums[m] > nums[r]:
                l = m + 1
            else:
                r = m

        pivot = l

        def binary_search(left: int, right: int) -> int:
            while left <= right:
                mid = (left + right) // 2
                if nums[mid] == target:
                    return mid
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1
            return -1

        result = binary_search(0, pivot - 1)
        if result != -1:
            return result

        return binary_search(pivot, len(nums) - 1)

class Solution {
    func myPow(_ x: Double, _ n: Int) -> Double {
        if x == 0 {
            return 0
        }
        if n == 0 {
            return 1
        }

        var res: Double = 1
        var base = x
        var power = abs(n)

        while power > 0 {
            if power & 1 == 1 {
                res *= base
            }
            base *= base
            power >>= 1
        }

        return n >= 0 ? res : 1 / res
    }
}

class Solution {
    fun climbStairs(n: Int): Int {
        if (n == 1) return 1

        val M = arrayOf(intArrayOf(1, 1), intArrayOf(1, 0))
        val result = matrixPow(M, n)

        return result[0][0]
    }

    private fun matrixMult(A: Array<IntArray>, B: Array<IntArray>): Array<IntArray> {
        return arrayOf(
            intArrayOf(A[0][0] * B[0][0] + A[0][1] * B[1][0],
                       A[0][0] * B[0][1] + A[0][1] * B[1][1]),
            intArrayOf(A[1][0] * B[0][0] + A[1][1] * B[1][0],
                       A[1][0] * B[0][1] + A[1][1] * B[1][1])
        )
    }

    private fun matrixPow(M: Array<IntArray>, p: Int): Array<IntArray> {
        var result = arrayOf(intArrayOf(1, 0), intArrayOf(0, 1))
        var base = M
        var power = p

        while (power > 0) {
            if (power % 2 == 1) {
                result = matrixMult(result, base)
            }
            base = matrixMult(base, base)
            power /= 2
        }

        return result
    }
}

