func matrixPow(M [][]int, p int) [][]int {
    result := [][]int{{1, 0}, {0, 1}}
    base := M

    for p > 0 {
        if p%2 == 1 {
            result = matrixMult(result, base)
        }
        base = matrixMult(base, base)
        p /= 2
    }

    return result
}

