public class Solution {
    public int climbStairs(int n) {
        if (n <= 2) {
            return n;
        }
        int[] dp = new int[n + 1];
        dp[1] = 1;
        dp[2] = 2;
        for (int i = 3; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }
}

func canFinish(numCourses int, prerequisites [][]int) bool {
    indegree := make([]int, numCourses)
    adj := make([][]int, numCourses)
    for i := 0; i < numCourses; i++ {
        adj[i] = []int{}
    }

    for _, prereq := range prerequisites {
        src, dst := prereq[0], prereq[1]
        indegree[dst]++
        adj[src] = append(adj[src], dst)
    }

    q := []int{}
    for n := 0; n < numCourses; n++ {
        if indegree[n] == 0 {
            q = append(q, n)
        }
    }

    finish := 0
    for len(q) > 0 {
        node := q[0]
        q = q[1:]
        finish++
        for _, nei := range adj[node] {
            indegree[nei]--
            if indegree[nei] == 0 {
                q = append(q, nei)
            }
        }
    }

    return finish == numCourses
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    func isSameTree(_ p: TreeNode?, _ q: TreeNode?) -> Bool {
        var q1 = Deque<TreeNode?>()
        var q2 = Deque<TreeNode?>()
        q1.append(p)
        q2.append(q)

        while !q1.isEmpty && !q2.isEmpty {
            let nodeP = q1.removeFirst()
            let nodeQ = q2.removeFirst()

            if nodeP == nil && nodeQ == nil {
                continue
            }
            if nodeP == nil || nodeQ == nil || nodeP!.val != nodeQ!.val {
                return false
            }

            q1.append(nodeP!.left)
            q1.append(nodeP!.right)
            q2.append(nodeQ!.left)
            q2.append(nodeQ!.right)
        }

        return true
    }
}

class Solution {
    /**
     * @param {number[]} nums
     * @return {number}
     */
    rob(nums) {
        if (nums.length === 1) return nums[0];

        const n = nums.length;
        const memo = Array.from({ length: n }, () => Array(2).fill(-1));

        const dfs = (i, flag) => {
            if (i >= n || (flag && i === n - 1)) return 0;
            if (memo[i][flag] !== -1) return memo[i][flag];

            memo[i][flag] = Math.max(
                dfs(i + 1, flag),
                nums[i] + dfs(i + 2, flag | (i === 0)),
            );
            return memo[i][flag];
        };

        return Math.max(dfs(0, 1), dfs(1, 0));
    }
}

