public class Solution {
    public ListNode MergeKLists(ListNode[] lists) {
        List<int> nodes = new List<int>();
        foreach (ListNode lst in lists) {
            ListNode curr = lst;
            while (curr != null) {
                nodes.Add(curr.val);
                curr = curr.next;
            }
        }
        nodes.Sort();

        ListNode res = new ListNode(0);
        ListNode cur = res;
        foreach (int node in nodes) {
            cur.next = new ListNode(node);
            cur = cur.next;
        }
        return res.next;
    }
}

struct MinIdxSegtree {
    n: usize,
    a: Vec<i32>,
    tree: Vec<usize>,
}

impl MinIdxSegtree {
    const INF: i32 = 1_000_000_000;

    fn new(n: usize, heights: &[i32]) -> Self {
        let mut a: Vec<i32> = heights.to_vec();
        let mut sz = n;
        while sz & (sz - 1) != 0 {
            a.push(Self::INF);
            sz += 1;
        }
        let mut st = MinIdxSegtree {
            n: sz,
            a,
            tree: vec![0; 2 * sz],
        };
        st.build();
        st
    }

    fn build(&mut self) {
        for i in 0..self.n {
            self.tree[self.n + i] = i;
        }
        for j in (1..self.n).rev() {
            let a = self.tree[j << 1];
            let b = self.tree[(j << 1) + 1];
            self.tree[j] = if self.a[a] <= self.a[b] { a } else { b };
        }
    }

    fn query(&self, ql: i32, qh: i32) -> usize {
        self.query_helper(1, 0, self.n as i32 - 1, ql, qh)
    }

    fn query_helper(&self, node: usize, l: i32, h: i32, ql: i32, qh: i32) -> usize {
        if ql > h || qh < l {
            return self.n; // sentinel
        }
        if l >= ql && h <= qh {
            return self.tree[node];
        }
        let mid = (l + h) >> 1;
        let a = self.query_helper(node << 1, l, mid, ql, qh);
        let b = self.query_helper((node << 1) + 1, mid + 1, h, ql, qh);
        if a >= self.n { return b; }
        if b >= self.n { return a; }
        if self.a[a] <= self.a[b] { a } else { b }
    }
}

impl Solution {
    pub fn largest_rectangle_area(heights: Vec<i32>) -> i32 {
        let n = heights.len();
        let st = MinIdxSegtree::new(n, &heights);

        fn get_max_area(heights: &[i32], l: i32, r: i32, st: &MinIdxSegtree) -> i32 {
            if l > r { return 0; }
            if l == r { return heights[l as usize]; }
            let min_idx = st.query(l, r) as i32;
            let area = (r - l + 1) * heights[min_idx as usize];
            let left_area = get_max_area(heights, l, min_idx - 1, st);
            let right_area = get_max_area(heights, min_idx + 1, r, st);
            area.max(left_area).max(right_area)
        }

        get_max_area(&heights, 0, n as i32 - 1, &st)
    }
}

public class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
        int n = intervals.length;
        int[] dp = new int[n];
        dp[0] = 1;

        for (int i = 1; i < n; i++) {
            int idx = bs(i, intervals[i][0], intervals);
            if (idx == 0) {
                dp[i] = dp[i - 1];
            } else {
                dp[i] = Math.max(dp[i - 1], 1 + dp[idx - 1]);
            }
        }
        return n - dp[n - 1];
    }

    private int bs(int r, int target, int[][] intervals) {
        int l = 0;
        while (l < r) {
            int m = (l + r) >> 1;
            if (intervals[m][1] <= target) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

class SegmentTree(N: Int) {
    var n: Int = N
    var tree: IntArray

    init {
        while ((n and (n - 1)) != 0) {
            n++
        }
        tree = IntArray(2 * n)
    }

    fun update(i: Int, value: Int) {
        tree[n + i] = value
        var j = (n + i) / 2
        while (j >= 1) {
            tree[j] = max(tree[j * 2], tree[j * 2 + 1])
            j /= 2
        }
    }

    fun query(l: Int, r: Int): Int {
        if (l > r) return 0
        var res = Int.MIN_VALUE
        var left = l + n
        var right = r + n + 1
        while (left < right) {
            if (left and 1 != 0) {
                res = max(res, tree[left])
                left++
            }
            if (right and 1 != 0) {
                right--
                res = max(res, tree[right])
            }
            left /= 2
            right /= 2
        }
        return res
    }
}

class Solution {
    fun compress(arr: IntArray): IntArray {
        val sortedArr = arr.toSortedSet().toIntArray()
        return arr.map { sortedArr.binarySearch(it) }.toIntArray()
    }

    fun lengthOfLIS(nums: IntArray): Int {
        val compressedNums = compress(nums)
        val n = compressedNums.size
        val segTree = SegmentTree(n)
        var LIS = 0
        for (num in compressedNums) {
            val curLIS = segTree.query(0, num - 1) + 1
            segTree.update(num, curLIS)
            LIS = max(LIS, curLIS)
        }
        return LIS
    }
}

