class Solution {
public:
    bool isNStraightHand(vector<int>& hand, int groupSize) {
        if (hand.size() % groupSize != 0) return false;

        map<int, int> count;
        for (int num : hand) count[num]++;

        queue<int> q;
        int lastNum = -1, openGroups = 0;

        for (auto& entry : count) {
            int num = entry.first;
            if ((openGroups > 0 && num > lastNum + 1) ||
                 openGroups > count[num]) {
                return false;
            }

            q.push(count[num] - openGroups);
            lastNum = num;
            openGroups = count[num];

            if (q.size() == groupSize) {
                openGroups -= q.front();
                q.pop();
            }
        }
        return openGroups == 0;
    }
};

public class Solution {
    public int[] MinInterval(int[][] intervals, int[] queries) {
        Array.Sort(intervals, (a, b) => a[0].CompareTo(b[0]));

        var minHeap = new PriorityQueue<(int Size, int End), int>();
        var res = new Dictionary<int, int>();
        int i = 0;

        int[] sortedQueries = queries.OrderBy(q => q).ToArray();
        foreach (int q in sortedQueries) {
            while (i < intervals.Length && intervals[i][0] <= q) {
                int l = intervals[i][0];
                int r = intervals[i][1];
                minHeap.Enqueue((r - l + 1, r), r - l + 1);
                i++;
            }

            while (minHeap.Count > 0 && minHeap.Peek().End < q) {
                minHeap.Dequeue();
            }

            res[q] = minHeap.Count == 0 ? -1 : minHeap.Peek().Size;
        }

        int[] result = new int[queries.Length];
        for (int j = 0; j < queries.Length; j++) {
            result[j] = res[queries[j]];
        }

        return result;
    }
}

public class Solution {
    int[][] directions = new int[][] {
        new int[] {-1, 0}, new int[] {1, 0},
        new int[] {0, -1}, new int[] {0, 1}
    };
    int[,] dp;

    private int Dfs(int[][] matrix, int r, int c, int prevVal) {
        int ROWS = matrix.Length, COLS = matrix[0].Length;
        if (r < 0 || r >= ROWS || c < 0 ||
            c >= COLS || matrix[r][c] <= prevVal) {
            return 0;
        }
        if (dp[r, c] != -1) return dp[r, c];

        int res = 1;
        foreach (int[] d in directions) {
            res = Math.Max(res, 1 + Dfs(matrix, r + d[0],
                                    c + d[1], matrix[r][c]));
        }

        dp[r, c] = res;
        return res;
    }

    public int LongestIncreasingPath(int[][] matrix) {
        int ROWS = matrix.Length, COLS = matrix[0].Length;
        dp = new int[ROWS, COLS];

        for (int i = 0; i < ROWS; i++) {
            for (int j = 0; j < COLS; j++) {
                dp[i, j] = -1;
            }
        }

        int LIP = 0;
        for (int r = 0; r < ROWS; r++) {
            for (int c = 0; c < COLS; c++) {
                LIP = Math.Max(LIP, Dfs(matrix, r, c, int.MinValue));
            }
        }
        return LIP;
    }
}

class Solution {
    /**
     * @param {number} m
     * @param {number} n
     * @return {number}
     */
    uniquePaths(m, n) {
        const memo = Array.from({ length: m }, () => Array(n).fill(-1));
        const dfs = (i, j) => {
            if (i == m - 1 && j == n - 1) {
                return 1;
            }
            if (i >= m || j >= n) return 0;
            if (memo[i][j] != -1) {
                return memo[i][j];
            }
            memo[i][j] = dfs(i, j + 1) + dfs(i + 1, j);
            return memo[i][j];
        };

        return dfs(0, 0);
    }
}

class DSU:
    def __init__(self, n):
        self.Parent = list(range(n + 1))
        self.Size = [1] * (n + 1)

    def find(self, node):
        if self.Parent[node] != node:
            self.Parent[node] = self.find(self.Parent[node])
        return self.Parent[node]

    def union(self, u, v):
        pu = self.find(u)
        pv = self.find(v)
        if pu == pv:
            return False
        if self.Size[pu] >= self.Size[pv]:
            self.Size[pu] += self.Size[pv]
            self.Parent[pv] = pu
        else:
            self.Size[pv] += self.Size[pu]
            self.Parent[pu] = pv
        return True

    def getSize(self, node):
        par = self.find(node)
        return self.Size[par]

class Solution:
    def maxAreaOfIsland(self, grid: List[List[int]]) -> int:
        ROWS, COLS = len(grid), len(grid[0])
        dsu = DSU(ROWS * COLS)

        def index(r, c):
            return r * COLS + c

        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        area = 0

        for r in range(ROWS):
            for c in range(COLS):
                if grid[r][c] == 1:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if (nr < 0 or nc < 0 or nr >= ROWS or
                            nc >= COLS or grid[nr][nc] == 0
                        ):
                            continue

                        dsu.union(index(r, c), index(nr, nc))

                    area = max(area, dsu.getSize(index(r, c)))

        return area

struct DSU {
    parent: Vec<usize>,
    size: Vec<usize>,
}

impl DSU {
    fn new(n: usize) -> Self {
        Self {
            parent: (0..=n).collect(),
            size: vec![1; n + 1],
        }
    }

    fn find(&mut self, node: usize) -> usize {
        if self.parent[node] != node {
            self.parent[node] = self.find(self.parent[node]);
        }
        self.parent[node]
    }

    fn union(&mut self, u: usize, v: usize) -> bool {
        let pu = self.find(u);
        let pv = self.find(v);
        if pu == pv {
            return false;
        }
        if self.size[pu] >= self.size[pv] {
            self.size[pu] += self.size[pv];
            self.parent[pv] = pu;
        } else {
            self.size[pv] += self.size[pu];
            self.parent[pu] = pv;
        }
        true
    }

    fn get_size(&mut self, node: usize) -> usize {
        let p = self.find(node);
        self.size[p]
    }
}

impl Solution {
    pub fn max_area_of_island(grid: Vec<Vec<i32>>) -> i32 {
        let rows = grid.len();
        let cols = grid[0].len();
        let mut dsu = DSU::new(rows * cols);

        let directions: [(i32, i32); 4] = [(1, 0), (-1, 0), (0, 1), (0, -1)];
        let mut area = 0usize;

        let index = |r: usize, c: usize| r * cols + c;

        for r in 0..rows {
            for c in 0..cols {
                if grid[r][c] == 1 {
                    for &(dr, dc) in &directions {
                        let nr = r as i32 + dr;
                        let nc = c as i32 + dc;
                        if nr < 0 || nc < 0 || nr >= rows as i32
                            || nc >= cols as i32
                            || grid[nr as usize][nc as usize] == 0
                        {
                            continue;
                        }
                        dsu.union(index(r, c), index(nr as usize, nc as usize));
                    }
                    area = area.max(dsu.get_size(index(r, c)));
                }
            }
        }

        area as i32
    }
}

public class Solution {
    private int[][] dp;
    public int minDistance(String word1, String word2) {
        int m = word1.length(), n = word2.length();
        dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = -1;
            }
        }
        return dfs(0, 0, word1, word2, m, n);
    }

    private int dfs(int i, int j, String word1, String word2, int m, int n) {
        if (i == m) return n - j;
        if (j == n) return m - i;
        if (dp[i][j] != -1) return dp[i][j];

        if (word1.charAt(i) == word2.charAt(j)) {
            dp[i][j] = dfs(i + 1, j + 1, word1, word2, m, n);
        } else {
            int res = Math.min(dfs(i + 1, j, word1, word2, m, n),
                            dfs(i, j + 1, word1, word2, m, n));
            res = Math.min(res, dfs(i + 1, j + 1, word1, word2, m, n));
            dp[i][j] = res + 1;
        }
        return dp[i][j];
    }
}

class Solution {
    func lengthOfLIS(_ nums: [Int]) -> Int {
        let n = nums.count
        var memo = Array(repeating: Array(repeating: -1, count: n + 1), count: n)

        func dfs(_ i: Int, _ j: Int) -> Int {
            if i == n {
                return 0
            }
            if memo[i][j + 1] != -1 {
                return memo[i][j + 1]
            }

            var LIS = dfs(i + 1, j) // not include

            if j == -1 || nums[j] < nums[i] {
                LIS = max(LIS, 1 + dfs(i + 1, i)) // include
            }

            memo[i][j + 1] = LIS
            return LIS
        }

        return dfs(0, -1)
    }
}

class Solution {
public:
    int countSubstrings(string s) {
        int res = 0, n = s.length();
        vector<vector<bool>> dp(n, vector<bool>(n, false));

        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (s[i] == s[j] &&
                    (j - i <= 2 || dp[i + 1][j - 1])) {

                    dp[i][j] = true;
                    res++;
                }
            }
        }

        return res;
    }
};

class Solution {
    fun findTargetSumWays(nums: IntArray, target: Int): Int {
        val dp = mutableMapOf(0 to 1)

        for (num in nums) {
            val nextDp = mutableMapOf<Int, Int>()
            for ((total, count) in dp) {
                nextDp[total + num] = nextDp.getOrDefault(total + num, 0) + count
                nextDp[total - num] = nextDp.getOrDefault(total - num, 0) + count
            }
            dp.clear()
            dp.putAll(nextDp)
        }

        return dp[target] ?: 0
    }
}

type Twitter struct {
    time      int
    followMap map[int]map[int]bool
    tweetMap  map[int][]Tweet
}

type Tweet struct {
    time    int
    tweetId int
}

func Constructor() Twitter {
    return Twitter{
        time:      0,
        followMap: make(map[int]map[int]bool),
        tweetMap:  make(map[int][]Tweet),
    }
}

func (this *Twitter) PostTweet(userId int, tweetId int) {
    this.tweetMap[userId] = append(this.tweetMap[userId], Tweet{this.time, tweetId})
    this.time++
}

func (this *Twitter) GetNewsFeed(userId int) []int {
    feed := make([]Tweet, 0)
    feed = append(feed, this.tweetMap[userId]...)

    if follows, ok := this.followMap[userId]; ok {
        for followeeId := range follows {
            feed = append(feed, this.tweetMap[followeeId]...)
        }
    }

    sort.Slice(feed, func(i, j int) bool {
        return feed[i].time > feed[j].time
    })

    result := make([]int, 0)
    for i := 0; i < len(feed) && i < 10; i++ {
        result = append(result, feed[i].tweetId)
    }
    return result
}

func (this *Twitter) Follow(followerId int, followeeId int) {
    if followerId != followeeId {
        if this.followMap[followerId] == nil {
            this.followMap[followerId] = make(map[int]bool)
        }
        this.followMap[followerId][followeeId] = true
    }
}

