public class Solution {
    public bool CheckValidString(string s) {
        int n = s.Length;
        bool[,] dp = new bool[n + 1, n + 1];
        dp[n, 0] = true;

        for (int i = n - 1; i >= 0; i--) {
            for (int open = 0; open < n; open++) {
                bool res = false;
                if (s[i] == '*') {
                    res |= dp[i + 1, open + 1];
                    if (open > 0) res |= dp[i + 1, open - 1];
                    res |= dp[i + 1, open];
                } else {
                    if (s[i] == '(') {
                        res |= dp[i + 1, open + 1];
                    } else if (open > 0) {
                        res |= dp[i + 1, open - 1];
                    }
                }
                dp[i, open] = res;
            }
        }
        return dp[0, 0];
    }
}

class Solution {
    /**
     * @param {string} s1
     * @param {string} s2
     * @param {string} s3
     * @return {boolean}
     */
    isInterleave(s1, s2, s3) {
        let m = s1.length,
            n = s2.length;
        if (m + n !== s3.length) {
            return false;
        }

        const dp = Array.from({ length: m + 1 }, () =>
            Array(n + 1).fill(false),
        );
        dp[m][n] = true;

        for (let i = m; i >= 0; i--) {
            for (let j = n; j >= 0; j--) {
                if (i < m && s1[i] === s3[i + j] && dp[i + 1][j]) {
                    dp[i][j] = true;
                }
                if (j < n && s2[j] === s3[i + j] && dp[i][j + 1]) {
                    dp[i][j] = true;
                }
            }
        }
        return dp[0][0];
    }
}

class Solution:
    def longestPalindrome(self, s: str) -> str:
        resIdx, resLen = 0, 0
        n = len(s)

        dp = [[False] * n for _ in range(n)]

        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                if s[i] == s[j] and (j - i <= 2 or dp[i + 1][j - 1]):
                    dp[i][j] = True
                    if resLen < (j - i + 1):
                        resIdx = i
                        resLen = j - i + 1

        return s[resIdx : resIdx + resLen]

impl Solution {
    pub fn rotate(matrix: &mut Vec<Vec<i32>>) {
        let mut l = 0;
        let mut r = matrix.len() - 1;
        while l < r {
            for i in 0..(r - l) {
                let top = l;
                let bottom = r;
                let top_left = matrix[top][l + i];
                matrix[top][l + i] = matrix[bottom - i][l];
                matrix[bottom - i][l] = matrix[bottom][r - i];
                matrix[bottom][r - i] = matrix[top + i][r];
                matrix[top + i][r] = top_left;
            }
            r -= 1;
            l += 1;
        }
    }
}

public class Solution {
    public int minCostConnectPoints(int[][] points) {
        int n = points.length, node = 0;
        int[] dist = new int[n];
        boolean[] visit = new boolean[n];
        Arrays.fill(dist, 100000000);
        int edges = 0, res = 0;

        while (edges < n - 1) {
            visit[node] = true;
            int nextNode = -1;
            for (int i = 0; i < n; i++) {
                if (visit[i]) continue;
                int curDist = Math.abs(points[i][0] - points[node][0]) +
                              Math.abs(points[i][1] - points[node][1]);
                dist[i] = Math.min(dist[i], curDist);
                if (nextNode == -1 || dist[i] < dist[nextNode]) {
                    nextNode = i;
                }
            }
            res += dist[nextNode];
            node = nextNode;
            edges++;
        }
        return res;
    }
}

class Solution {
    func maxAreaOfIsland(_ grid: [[Int]]) -> Int {
        let directions = [[1, 0], [-1, 0], [0, 1], [0, -1]]
        let ROWS = grid.count
        let COLS = grid[0].count
        var grid = grid
        var area = 0

        func bfs(_ r: Int, _ c: Int) -> Int {
            var queue = Deque<(Int, Int)>()
            grid[r][c] = 0
            queue.append((r, c))
            var res = 1

            while !queue.isEmpty {
                let (row, col) = queue.popFirst()!
                for dir in directions {
                    let nr = row + dir[0]
                    let nc = col + dir[1]
                    if nr < 0 || nc < 0 || nr >= ROWS || nc >= COLS || grid[nr][nc] == 0 {
                        continue
                    }
                    queue.append((nr, nc))
                    grid[nr][nc] = 0
                    res += 1
                }
            }
            return res
        }

        for r in 0..<ROWS {
            for c in 0..<COLS {
                if grid[r][c] == 1 {
                    area = max(area, bfs(r, c))
                }
            }
        }

        return area
    }
}

class Solution {
    vector<vector<int>> dp;
    int totalSum;

public:
    int findTargetSumWays(vector<int>& nums, int target) {
        totalSum = accumulate(nums.begin(), nums.end(), 0);
        dp = vector<vector<int>>(nums.size(), vector<int>(2 * totalSum + 1, INT_MIN));
        return backtrack(0, 0, nums, target);
    }

    int backtrack(int i, int total, vector<int>& nums, int target) {
        if (i == nums.size()) {
            return total == target;
        }
        if (dp[i][total + totalSum] != INT_MIN) {
            return dp[i][total + totalSum];
        }
        dp[i][total + totalSum] = backtrack(i + 1, total + nums[i], nums, target) +
                                  backtrack(i + 1, total - nums[i], nums, target);
        return dp[i][total + totalSum];
    }
};

class Solution {
    fun pacificAtlantic(heights: Array<IntArray>): List<List<Int>> {
        val rows = heights.size
        val cols = heights[0].size
        val directions = arrayOf(intArrayOf(1, 0),
                                 intArrayOf(-1, 0),
                                 intArrayOf(0, 1),
                                 intArrayOf(0, -1))

        val pac = Array(rows) { BooleanArray(cols) }
        val atl = Array(rows) { BooleanArray(cols) }

        fun bfs(source: List<IntArray>, ocean: Array<BooleanArray>) {
            val q = LinkedList<IntArray>()
            q.addAll(source)
            while (q.isNotEmpty()) {
                val (r, c) = q.poll()
                ocean[r][c] = true
                for (dir in directions) {
                    val nr = r + dir[0]
                    val nc = c + dir[1]
                    if (nr in 0 until rows && nc in 0 until cols &&
                        !ocean[nr][nc] && heights[nr][nc] >= heights[r][c]) {
                        q.offer(intArrayOf(nr, nc))
                    }
                }
            }
        }

        val pacific = mutableListOf<IntArray>()
        val atlantic = mutableListOf<IntArray>()
        for (c in 0 until cols) {
            pacific.add(intArrayOf(0, c))
            atlantic.add(intArrayOf(rows - 1, c))
        }
        for (r in 0 until rows) {
            pacific.add(intArrayOf(r, 0))
            atlantic.add(intArrayOf(r, cols - 1))
        }

        bfs(pacific, pac)
        bfs(atlantic, atl)

        val result = mutableListOf<List<Int>>()
        for (r in 0 until rows) {
            for (c in 0 until cols) {
                if (pac[r][c] && atl[r][c]) {
                    result.add(listOf(r, c))
                }
            }
        }
        return result
    }
}

func minEatingSpeed(piles []int, h int) int {
   speed := 1
   for {
       totalTime := 0
       for _, pile := range piles {
           totalTime += int(math.Ceil(float64(pile) / float64(speed)))
       }

       if totalTime <= h {
           return speed
       }
       speed += 1
   }
   return speed
}

public class Solution {
    public List<int> SpiralOrder(int[][] matrix) {
        int m = matrix.Length, n = matrix[0].Length;
        List<int> res = new List<int>();

        // append all the elements in the given direction
        Dfs(m, n, 0, -1, 0, 1, matrix, res);
        return res;
    }

    private void Dfs(int row, int col, int r, int c, int dr,
                     int dc, int[][] matrix, List<int> res) {
        if (row == 0 || col == 0) return;

        for (int i = 0; i < col; i++) {
            r += dr;
            c += dc;
            res.Add(matrix[r][c]);
        }

        // sub-problem
        Dfs(col, row - 1, r, c, dc, -dr, matrix, res);
    }
}

class Solution {
    /**
     * @param {number[][]} matrix
     * @return {void}
     */
    setZeroes(matrix) {
        const ROWS = matrix.length,
            COLS = matrix[0].length;
        const mark = matrix.map((row) => [...row]);

        for (let r = 0; r < ROWS; r++) {
            for (let c = 0; c < COLS; c++) {
                if (matrix[r][c] === 0) {
                    for (let col = 0; col < COLS; col++) {
                        mark[r][col] = 0;
                    }
                    for (let row = 0; row < ROWS; row++) {
                        mark[row][c] = 0;
                    }
                }
            }
        }

        for (let r = 0; r < ROWS; r++) {
            for (let c = 0; c < COLS; c++) {
                matrix[r][c] = mark[r][c];
            }
        }
    }
}

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        ROWS, COLS = len(matrix), len(matrix[0])
        dp = {}  # (r, c) -> LIP

        def dfs(r, c, prevVal):
            if (r < 0 or r == ROWS or c < 0 or
                c == COLS or matrix[r][c] <= prevVal
            ):
                return 0
            if (r, c) in dp:
                return dp[(r, c)]

            res = 1
            res = max(res, 1 + dfs(r + 1, c, matrix[r][c]))
            res = max(res, 1 + dfs(r - 1, c, matrix[r][c]))
            res = max(res, 1 + dfs(r, c + 1, matrix[r][c]))
            res = max(res, 1 + dfs(r, c - 1, matrix[r][c]))
            dp[(r, c)] = res
            return res

        for r in range(ROWS):
            for c in range(COLS):
                dfs(r, c, -1)
        return max(dp.values())

impl Solution {
    pub fn is_valid_sudoku(board: Vec<Vec<char>>) -> bool {
        let mut rows = [0i32; 9];
        let mut cols = [0i32; 9];
        let mut squares = [0i32; 9];

        for r in 0..9 {
            for c in 0..9 {
                if board[r][c] == '.' { continue; }

                let val = board[r][c] as i32 - '1' as i32;
                let bit = 1 << val;
                let square_idx = (r / 3) * 3 + c / 3;

                if (rows[r] & bit) != 0
                    || (cols[c] & bit) != 0
                    || (squares[square_idx] & bit) != 0
                {
                    return false;
                }

                rows[r] |= bit;
                cols[c] |= bit;
                squares[square_idx] |= bit;
            }
        }

        true
    }
}

public class Solution {
    private Map<Integer, Boolean> memo;

    public boolean wordBreak(String s, List<String> wordDict) {
        memo = new HashMap<>();
        memo.put(s.length(), true);
        return dfs(s, wordDict, 0);
    }

    private boolean dfs(String s, List<String> wordDict, int i) {
        if (memo.containsKey(i)) {
            return memo.get(i);
        }

        for (String w : wordDict) {
            if (i + w.length() <= s.length() &&
                s.substring(i, i + w.length()).equals(w)) {
                if (dfs(s, wordDict, i + w.length())) {
                    memo.put(i, true);
                    return true;
                }
            }
        }
        memo.put(i, false);
        return false;
    }
}

class Solution {
    func trap(_ height: [Int]) -> Int {
        if height.isEmpty {
            return 0
        }
        let n = height.count
        var res = 0

        for i in 0..<n {
            var leftMax = height[i]
            var rightMax = height[i]

            for j in 0..<i {
                leftMax = max(leftMax, height[j])
            }
            for j in (i + 1)..<n {
                rightMax = max(rightMax, height[j])
            }

            res += min(leftMax, rightMax) - height[i]
        }
        return res
    }
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

class Solution {
public:
    int diameterOfBinaryTree(TreeNode* root) {
        if (!root) return 0;

        int leftHeight = maxHeight(root->left);
        int rightHeight = maxHeight(root->right);
        int diameter = leftHeight + rightHeight;
        int sub = max(diameterOfBinaryTree(root->left),
                      diameterOfBinaryTree(root->right));
        return max(diameter, sub);
    }

    int maxHeight(TreeNode* root) {
        if (!root) return 0;
        return 1 + max(maxHeight(root->left), maxHeight(root->right));
    }
};

func countSubstrings(s string) int {
    res := 0
    for i := range s {
        for j := i; j < len(s); j++ {
            l, r := i, j
            for l < r && s[l] == s[r] {
                l++
                r--
            }
            if l >= r {
                res++
            }
        }
    }
    return res
}

public class Solution {
    public int maxCoins(int[] nums) {
        int n = nums.length;
        int[] newNums = new int[n + 2];
        newNums[0] = newNums[n + 1] = 1;
        for (int i = 0; i < n; i++) {
            newNums[i + 1] = nums[i];
        }

        int[][] dp = new int[n + 2][n + 2];
        for (int l = n; l >= 1; l--) {
            for (int r = l; r <= n; r++) {
                for (int i = l; i <= r; i++) {
                    int coins = newNums[l - 1] * newNums[i] * newNums[r + 1];
                    coins += dp[l][i - 1] + dp[i + 1][r];
                    dp[l][r] = Math.max(dp[l][r], coins);
                }
            }
        }

        return dp[1][n];
    }
}

impl Solution {
    pub fn count_substrings(s: String) -> i32 {
        let s = s.as_bytes();
        let mut res = 0;

        for i in 0..s.len() {
            for j in i..s.len() {
                let (mut l, mut r) = (i, j);
                while l < r && s[l] == s[r] {
                    l += 1;
                    r -= 1;
                }
                if l >= r {
                    res += 1;
                }
            }
        }

        res
    }
}

class Solution {
    func threeSum(_ nums: [Int]) -> [[Int]] {
        var res = Set<[Int]>()
        let nums = nums.sorted()

        for i in 0..<nums.count {
            for j in (i + 1)..<nums.count {
                for k in (j + 1)..<nums.count {
                    if nums[i] + nums[j] + nums[k] == 0 {
                        let tmp = [nums[i], nums[j], nums[k]]
                        res.insert(tmp)
                    }
                }
            }
        }
        return Array(res)
    }
}

class Solution {
    fun longestPalindrome(s: String): String {
        var res = ""
        var resLen = 0

        for (i in s.indices) {
            for (j in i until s.length) {
                var l = i
                var r = j
                while (l < r && s[l] == s[r]) {
                    l++
                    r--
                }

                if (l >= r && resLen < (j - i + 1)) {
                    res = s.substring(i, j + 1)
                    resLen = j - i + 1
                }
            }
        }

        return res
    }
}

class Solution:
