class Solution {
    /**
     * @param {string} s
     * @param {string[]} wordDict
     * @return {boolean}
     */
    wordBreak(s, wordDict) {
        this.wordSet = new Set(wordDict);
        this.memo = new Array(s.length).fill(null);
        this.t = 0;
        for (const w of wordDict) {
            this.t = Math.max(this.t, w.length);
        }
        return this.dfs(s, 0);
    }

    /**
     * @param {string} s
     * @param {number} i
     * @return {boolean}
     */
    dfs(s, i) {
        if (i === s.length) {
            return true;
        }
        if (this.memo[i] !== null) {
            return this.memo[i];
        }

        for (let j = i; j < Math.min(i + this.t, s.length); j++) {
            if (this.wordSet.has(s.substring(i, j + 1))) {
                if (this.dfs(s, j + 1)) {
                    this.memo[i] = true;
                    return true;
                }
            }
        }
        this.memo[i] = false;
        return false;
    }
}

func checkInclusion(s1 string, s2 string) bool {
	s1Sorted := []rune(s1)
	sort.Slice(s1Sorted, func(i, j int) bool {
		return s1Sorted[i] < s1Sorted[j]
	})
	s1 = string(s1Sorted)

	for i := 0; i < len(s2); i++ {
		for j := i; j < len(s2); j++ {
			subStr := s2[i : j+1]
			subStrSorted := []rune(subStr)
			sort.Slice(subStrSorted, func(a, b int) bool {
				return subStrSorted[a] < subStrSorted[b]
			})
			if string(subStrSorted) == s1 {
				return true
			}
		}
	}
	return false
}

public class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty()) return "";

        Map<Character, Integer> countT = new HashMap<>();
        for (char c : t.toCharArray()) {
            countT.put(c, countT.getOrDefault(c, 0) + 1);
        }

        int[] res = {-1, -1};
        int resLen = Integer.MAX_VALUE;

        for (int i = 0; i < s.length(); i++) {
            Map<Character, Integer> countS = new HashMap<>();
            for (int j = i; j < s.length(); j++) {
                countS.put(s.charAt(j), countS.getOrDefault(s.charAt(j), 0) + 1);

                boolean flag = true;
                for (char c : countT.keySet()) {
                    if (countS.getOrDefault(c, 0) < countT.get(c)) {
                        flag = false;
                        break;
                    }
                }

                if (flag && (j - i + 1) < resLen) {
                    resLen = j - i + 1;
                    res[0] = i;
                    res[1] = j;
                }
            }
        }

        return resLen == Integer.MAX_VALUE ? "" : s.substring(res[0], res[1] + 1);
    }
}

impl Solution {
    pub fn ladder_length(begin_word: String, end_word: String, word_list: Vec<String>) -> i32 {
        if !word_list.contains(&end_word) || begin_word == end_word {
            return 0;
        }

        let n = word_list.len();
        let m = word_list[0].len();
        let mut adj = vec![vec![]; n];
        let mut mp = HashMap::new();
        for i in 0..n {
            mp.insert(&word_list[i], i);
        }

        let words_bytes: Vec<&[u8]> = word_list.iter().map(|w| w.as_bytes()).collect();
        for i in 0..n {
            for j in (i + 1)..n {
                let cnt = (0..m).filter(|&k| words_bytes[i][k] != words_bytes[j][k]).count();
                if cnt == 1 {
                    adj[i].push(j);
                    adj[j].push(i);
                }
            }
        }

        let mut q = VecDeque::new();
        let mut res = 1;
        let mut visit = HashSet::new();
        let begin_bytes = begin_word.as_bytes();

        for i in 0..m {
            for c in b'a'..=b'z' {
                if c == begin_bytes[i] {
                    continue;
                }
                let mut word = begin_word.clone().into_bytes();
                word[i] = c;
                let word = String::from_utf8(word).unwrap();
                if let Some(&idx) = mp.get(&word) {
                    if visit.insert(idx) {
                        q.push_back(idx);
                    }
                }
            }
        }

        while !q.is_empty() {
            res += 1;
            let size = q.len();
            for _ in 0..size {
                let node = q.pop_front().unwrap();
                if word_list[node] == end_word {
                    return res;
                }
                for &nei in &adj[node] {
                    if visit.insert(nei) {
                        q.push_back(nei);
                    }
                }
            }
        }

        0
    }
}

class Solution {
    func maxCoins(_ nums: [Int]) -> Int {
        let n = nums.count
        var newNums = [1] + nums + [1]

        var dp = Array(repeating: Array(repeating: 0, count: n + 2), count: n + 2)

        for l in stride(from: n, through: 1, by: -1) {
            for r in l...n {
                for i in l...r {
                    let coins = (newNums[l - 1] * newNums[i] * newNums[r + 1]) +
                                dp[l][i - 1] + dp[i + 1][r]
                    dp[l][r] = max(dp[l][r], coins)
                }
            }
        }

        return dp[1][n]
    }
}

class Solution {
    fun ladderLength(beginWord: String, endWord: String, wordList: List<String>): Int {
        if (!wordList.contains(endWord)) {
            return 0
        }

        val nei = HashMap<String, MutableList<String>>().withDefault { mutableListOf() }
        val allWords = wordList.toMutableList().apply { add(beginWord) }

        for (word in allWords) {
            for (j in word.indices) {
                val pattern = word.substring(0, j) + "*" + word.substring(j + 1)
                nei[pattern] = nei.getValue(pattern).apply { add(word) }
            }
        }

        val visit = hashSetOf(beginWord)
        val q = ArrayDeque<String>().apply { add(beginWord) }
        var res = 1

        while (q.isNotEmpty()) {
            repeat(q.size) {
                val word = q.removeFirst()

                if (word == endWord) {
                    return res
                }

                for (j in word.indices) {
                    val pattern = word.substring(0, j) + "*" + word.substring(j + 1)
                    for (neiWord in nei.getValue(pattern)) {
                        if (visit.add(neiWord)) {
                            q.add(neiWord)
                        }
                    }
                }
            }
            res++
        }
        return 0
    }
}

class Solution:
    def longestPalindrome(self, s: str) -> str:
        res, resLen = "", 0

        for i in range(len(s)):
            for j in range(i, len(s)):
                l, r = i, j
                while l < r and s[l] == s[r]:
                    l += 1
                    r -= 1

                if l >= r and resLen < (j - i + 1):
                    res = s[i : j + 1]
                    resLen = j - i + 1
        return res

public class Solution {
    private HashSet<string> wordSet;
    private Dictionary<int, bool> memo;
    private int t;

    public bool WordBreak(string s, List<string> wordDict) {
        wordSet = new HashSet<string>(wordDict);
        memo = new Dictionary<int, bool>();
        t = 0;
        foreach (var w in wordDict) {
            t = Math.Max(t, w.Length);
        }
        return Dfs(s, 0);
    }

    private bool Dfs(string s, int i) {
        if (i == s.Length) {
            return true;
        }
        if (memo.ContainsKey(i)) {
            return memo[i];
        }

        for (int j = i; j < Math.Min(i + t, s.Length); j++) {
            if (wordSet.Contains(s.Substring(i, j - i + 1))) {
                if (Dfs(s, j + 1)) {
                    memo[i] = true;
                    return true;
                }
            }
        }
        memo[i] = false;
        return false;
    }
}

class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        if (find(wordList.begin(), wordList.end(), endWord) == wordList.end() ||
            beginWord == endWord) {
            return 0;
        }

        int n = wordList.size();
        int m = wordList[0].size();
        vector<vector<int>> adj(n);
        unordered_map<string, int> mp;
        for (int i = 0; i < n; i++) {
            mp[wordList[i]] = i;
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int cnt = 0;
                for (int k = 0; k < m; k++) {
                    if (wordList[i][k] != wordList[j][k]) {
                        cnt++;
                    }
                }
                if (cnt == 1) {
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
            }
        }

        queue<int> q;
        int res = 1;
        unordered_set<int> visit;

        for (int i = 0; i < m; i++) {
            for (char c = 'a'; c <= 'z'; c++) {
                if (c == beginWord[i]) {
                    continue;
                }
                string word = beginWord.substr(0, i) + c + beginWord.substr(i + 1);
                if (mp.find(word) != mp.end() && visit.find(mp[word]) == visit.end()) {
                    q.push(mp[word]);
                    visit.insert(mp[word]);
                }
            }
        }

        while (!q.empty()) {
            res++;
            int size = q.size();
            for (int i = 0; i < size; i++) {
                int node = q.front();
                q.pop();
                if (wordList[node] == endWord) {
                    return res;
                }
                for (int nei : adj[node]) {
                    if (visit.find(nei) == visit.end()) {
                        visit.insert(nei);
                        q.push(nei);
                    }
                }
            }
        }

        return 0;
    }
};

class Solution {
    /**
     * @param {string} beginWord
     * @param {string} endWord
     * @param {string[]} wordList
     * @return {number}
     */
    ladderLength(beginWord, endWord, wordList) {
        if (!wordList.includes(endWord) || beginWord === endWord) {
            return 0;
        }
        const m = wordList[0].length;
        const wordSet = new Set(wordList);
        let qb = new Queue([beginWord]);
        let qe = new Queue([endWord]);
        let fromBegin = { [beginWord]: 1 };
        let fromEnd = { [endWord]: 1 };

        while (!qb.isEmpty() && !qe.isEmpty()) {
            if (qb.size() > qe.size()) {
                [qb, qe] = [qe, qb];
                [fromBegin, fromEnd] = [fromEnd, fromBegin];
            }
            const size = qb.size();
            for (let k = 0; k < size; k++) {
                const word = qb.pop();
                const steps = fromBegin[word];
                for (let i = 0; i < m; i++) {
                    for (let c = 97; c <= 122; c++) {
                        if (String.fromCharCode(c) === word[i]) continue;
                        const nei =
                            word.slice(0, i) +
                            String.fromCharCode(c) +
                            word.slice(i + 1);
                        if (!wordSet.has(nei)) continue;
                        if (fromEnd[nei] !== undefined)
                            return steps + fromEnd[nei];
                        if (fromBegin[nei] === undefined) {
                            fromBegin[nei] = steps + 1;
                            qb.push(nei);
                        }
                    }
                }
            }
        }
        return 0;
    }
}

func ladderLength(beginWord string, endWord string, wordList []string) int {
    if !contains(wordList, endWord) || beginWord == endWord {
        return 0
    }

    n, m := len(wordList), len(wordList[0])
    adj := make([][]int, n)
    mp := make(map[string]int)

    for i := 0; i < n; i++ {
        mp[wordList[i]] = i
    }

    for i := 0; i < n; i++ {
        for j := i + 1; j < n; j++ {
            cnt := 0
            for k := 0; k < m; k++ {
                if wordList[i][k] != wordList[j][k] {
                    cnt++
                }
            }
            if cnt == 1 {
                adj[i] = append(adj[i], j)
                adj[j] = append(adj[j], i)
            }
        }
    }

    q := []int{}
    res := 1
    visit := make(map[int]bool)

    for i := 0; i < m; i++ {
        for c := 'a'; c <= 'z'; c++ {
            if rune(beginWord[i]) == c {
                continue
            }
            word := beginWord[:i] + string(c) + beginWord[i+1:]
            if idx, exists := mp[word]; exists && !visit[idx] {
                q = append(q, idx)
                visit[idx] = true
            }
        }
    }

    for len(q) > 0 {
        res++
        size := len(q)
        for i := 0; i < size; i++ {
            node := q[0]
            q = q[1:]
            if wordList[node] == endWord {
                return res
            }
            for _, nei := range adj[node] {
                if !visit[nei] {
                    visit[nei] = true
                    q = append(q, nei)
                }
            }
        }
    }
    return 0
}

