class Solution {
    func ladderLength(_ beginWord: String, _ endWord: String, _ wordList: [String]) -> Int {
        if !wordList.contains(endWord) || beginWord == endWord {
            return 0
        }

        let n = wordList.count
        let m = wordList[0].count
        var adj = [[Int]](repeating: [], count: n)
        var mp = [String: Int]()

        for i in 0..<n {
            mp[wordList[i]] = i
        }

        let wordArrays = wordList.map { Array($0) }

        for i in 0..<n {
            for j in (i + 1)..<n {
                var cnt = 0
                let arr1 = wordArrays[i]
                let arr2 = wordArrays[j]
                for k in 0..<m {
                    if arr1[k] != arr2[k] {
                        cnt += 1
                    }
                }
                if cnt == 1 {
                    adj[i].append(j)
                    adj[j].append(i)
                }
            }
        }

        var q = Deque<Int>()
        var res = 1
        var visit = Set<Int>()
        let beginChars = Array(beginWord)

        for i in 0..<m {
            for c in 97...122 {
                let ch = Character(UnicodeScalar(c)!)
                if ch == beginChars[i] {
                    continue
                }
                let prefix = String(beginChars[0..<i])
                let suffix = i + 1 < beginChars.count ? String(beginChars[(i + 1)...]) : ""
                let word = prefix + String(ch) + suffix
                if let idx = mp[word], !visit.contains(idx) {
                    q.append(idx)
                    visit.insert(idx)
                }
            }
        }

        while !q.isEmpty {
            res += 1
            let levelCount = q.count
            for _ in 0..<levelCount {
                let node = q.removeFirst()
                if wordList[node] == endWord {
                    return res
                }
                for nei in adj[node] {
                    if !visit.contains(nei) {
                        visit.insert(nei)
                        q.append(nei)
                    }
                }
            }
        }

        return 0
    }
}

class Solution {
    fun maxCoins(nums: IntArray): Int {
        val newNums = intArrayOf(1) + nums + intArrayOf(1)
        val n = newNums.size
        val dp = Array(n) { IntArray(n) }

        fun dfs(l: Int, r: Int): Int {
            if (l > r) return 0
            if (dp[l][r] > 0) return dp[l][r]

            dp[l][r] = 0
            for (i in l..r) {
                val coins = newNums[l - 1] * newNums[i] * newNums[r + 1]
                val totalCoins = coins + dfs(l, i - 1) + dfs(i + 1, r)
                dp[l][r] = maxOf(dp[l][r], totalCoins)
            }
            return dp[l][r]
        }

        return dfs(1, newNums.size - 2)
    }
}

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        if endWord not in wordList:
            return 0

        nei = collections.defaultdict(list)
        wordList.append(beginWord)
        for word in wordList:
            for j in range(len(word)):
                pattern = word[:j] + "*" + word[j + 1 :]
                nei[pattern].append(word)

        visit = set([beginWord])
        q = deque([beginWord])
        res = 1
        while q:
            for i in range(len(q)):
                word = q.popleft()
                if word == endWord:
                    return res
                for j in range(len(word)):
                    pattern = word[:j] + "*" + word[j + 1 :]
                    for neiWord in nei[pattern]:
                        if neiWord not in visit:
                            visit.add(neiWord)
                            q.append(neiWord)
            res += 1
        return 0

public class Solution {
    public int MaxCoins(int[] nums) {
        int n = nums.Length;
        int[] newNums = new int[n + 2];
        newNums[0] = newNums[n + 1] = 1;
        for (int i = 0; i < n; i++) {
            newNums[i + 1] = nums[i];
        }

        int[,] dp = new int[n + 2, n + 2];
        for (int l = n; l >= 1; l--) {
            for (int r = l; r <= n; r++) {
                for (int i = l; i <= r; i++) {
                    int coins = newNums[l - 1] * newNums[i] * newNums[r + 1];
                    coins += dp[l, i - 1] + dp[i + 1, r];
                    dp[l, r] = Math.Max(dp[l, r], coins);
                }
            }
        }

        return dp[1, n];
    }
}

class Solution {
