        fun dfs(i: Int, flag: Boolean): Int {
            if (i == nums.size) {
                return if (flag) 0 else Int.MIN_VALUE
            }
            return if (flag) {
                maxOf(0, nums[i] + dfs(i + 1, true))
            } else {
                maxOf(dfs(i + 1, false), nums[i] + dfs(i + 1, true))
            }
        }

        return dfs(0, false)
    }
}

