func subsetsWithDup(nums []int) [][]int {
    var res [][]int
    sort.Ints(nums)

    var backtrack func(int, []int)
    backtrack = func(i int, subset []int) {
        if i == len(nums) {
            res = append(res, append([]int{}, subset...))
            return
        }

        subset = append(subset, nums[i])
        backtrack(i+1, subset)
        subset = subset[:len(subset)-1]

        for i+1 < len(nums) && nums[i] == nums[i+1] {
            i++
        }

        backtrack(i+1, subset)
    }

    backtrack(0, []int{})
    return res
}

class Solution {
    constructor() {
        this.res = [];
    }

    /**
     * @param {number[]} candidates
     * @param {number} target
     * @return {number[][]}
     */
    combinationSum2(candidates, target) {
        this.res = [];
        candidates.sort((a, b) => a - b);
        this.dfs(candidates, target, 0, [], 0);
        return this.res;
    }

    /**
     * @param {number[]} candidates
     * @param {number} target
     * @param {number} i
     * @param {number[]} cur
     * @param {number} total
     * @return {void}
     */
    dfs(candidates, target, i, cur, total) {
        if (total === target) {
            this.res.push([...cur]);
            return;
        }
        if (total > target || i === candidates.length) {
            return;
        }

        cur.push(candidates[i]);
        this.dfs(candidates, target, i + 1, cur, total + candidates[i]);
        cur.pop();

        while (
            i + 1 < candidates.length &&
            candidates[i] === candidates[i + 1]
        ) {
            i++;
        }
        this.dfs(candidates, target, i + 1, cur, total);
    }
}

impl Solution {
    pub fn num_distinct(s: String, t: String) -> i32 {
        let s = s.as_bytes();
        let t = t.as_bytes();
        if t.len() > s.len() {
            return 0;
        }

        fn dfs(s: &[u8], t: &[u8], i: usize, j: usize) -> i32 {
            if j == t.len() {
                return 1;
            }
            if i == s.len() {
                return 0;
            }
            let mut res = dfs(s, t, i + 1, j);
            if s[i] == t[j] {
                res += dfs(s, t, i + 1, j + 1);
            }
            res
        }

        dfs(s, t, 0, 0)
    }
}

