            if chars[i] == "(" {
                return dfs(i + 1, open + 1)
            } else if chars[i] == ")" {
                return dfs(i + 1, open - 1)
            } else {
                return dfs(i + 1, open) ||
                       dfs(i + 1, open + 1) ||
                       dfs(i + 1, open - 1)
            }
        }

        return dfs(0, 0)
    }
}

class Solution {
    fun rob(nums: IntArray): Int {
        val n = nums.size
        fun dfs(i: Int): Int {
            if (i >= n) return 0
            return maxOf(dfs(i + 1), nums[i] + dfs(i + 2))
        }
        return dfs(0)
    }
}

class Solution {
public:
    int minCostClimbingStairs(vector<int>& cost) {
        return min(dfs(cost, 0), dfs(cost, 1));
    }

    int dfs(vector<int>& cost, int i) {
        if (i >= cost.size()) {
            return 0;
        }
        return cost[i] + min(dfs(cost, i + 1),
                             dfs(cost, i + 2));
    }
};

class Solution:
    def combinationSum2(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        candidates.sort()

        def dfs(idx, path, cur):
            if cur == target:
                res.append(path.copy())
                return
            for i in range(idx, len(candidates)):
                if i > idx and candidates[i] == candidates[i - 1]:
                    continue
                if cur + candidates[i] > target:
                    break

                path.append(candidates[i])
                dfs(i + 1, path, cur + candidates[i])
                path.pop()

        dfs(0, [], 0)
        return res

func subsets(nums []int) [][]int {
    n := len(nums)
    res := [][]int{}

    for i := 0; i < (1 << n); i++ {
        subset := []int{}
        for j := 0; j < n; j++ {
            if (i & (1 << j)) != 0 {
                subset = append(subset, nums[j])
            }
        }
        res = append(res, subset)
    }

    return res
}

class Solution {
    /**
     * @param {string} s
     * @return {number}
     */
    numDecodings(s) {
        const dfs = (i) => {
            if (i === s.length) return 1;
            if (s[i] === '0') return 0;

            let res = dfs(i + 1);
            if (i < s.length - 1) {
                if (s[i] === '1' || (s[i] === '2' && s[i + 1] < '7')) {
                    res += dfs(i + 2);
                }
            }
            return res;
        };

        return dfs(0);
    }
}

struct TrieNode {
    children: [Option<Box<TrieNode>>; 26],
    idx: i32,
    refs: i32,
}

impl TrieNode {
    fn new() -> Self {
        TrieNode {
            children: Default::default(),
            idx: -1,
            refs: 0,
        }
    }

    fn add_word(&mut self, word: &str, i: i32) {
        let mut cur = self;
        cur.refs += 1;
        for c in word.bytes() {
            let index = (c - b'a') as usize;
            if cur.children[index].is_none() {
                cur.children[index] = Some(Box::new(TrieNode::new()));
            }
            cur = cur.children[index].as_mut().unwrap();
            cur.refs += 1;
        }
        cur.idx = i;
    }
}

impl Solution {
    pub fn find_words(mut board: Vec<Vec<char>>, words: Vec<String>) -> Vec<String> {
        let mut root = TrieNode::new();
        for (i, word) in words.iter().enumerate() {
            root.add_word(word, i as i32);
        }

        let rows = board.len();
        let cols = board[0].len();
        let mut res = Vec::new();

        for r in 0..rows {
            for c in 0..cols {
                Self::dfs(&mut board, &mut root, r as i32, c as i32,
                          &words, &mut res);
            }
        }
        res
    }

    fn dfs(
        board: &mut Vec<Vec<char>>, node: &mut TrieNode,
        r: i32, c: i32, words: &[String], res: &mut Vec<String>,
    ) {
        if r < 0 || c < 0 || r >= board.len() as i32
            || c >= board[0].len() as i32
        {
            return;
        }
        let (ru, cu) = (r as usize, c as usize);
        if board[ru][cu] == '*' { return; }
        let idx = (board[ru][cu] as u8 - b'a') as usize;
        if node.children[idx].is_none() { return; }

        let tmp = board[ru][cu];
        board[ru][cu] = '*';
        let child = node.children[idx].as_mut().unwrap();

        if child.idx != -1 {
            res.push(words[child.idx as usize].clone());
            child.idx = -1;
            child.refs -= 1;
            if child.refs == 0 {
                node.children[idx] = None;
                board[ru][cu] = tmp;
                return;
            }
        }

        let child = node.children[idx].as_mut().unwrap();
        Self::dfs(board, child, r + 1, c, words, res);
        Self::dfs(board, child, r - 1, c, words, res);
        Self::dfs(board, child, r, c + 1, words, res);
        Self::dfs(board, child, r, c - 1, words, res);

        board[ru][cu] = tmp;
    }
}

public class Solution {
    public int FindTargetSumWays(int[] nums, int target) {
        return Backtrack(0, 0, nums, target);
    }

    private int Backtrack(int i, int total, int[] nums, int target) {
        if (i == nums.Length) {
            return total == target ? 1 : 0;
        }
        return Backtrack(i + 1, total + nums[i], nums, target) +
               Backtrack(i + 1, total - nums[i], nums, target);
    }
}

public class Solution {
    private void backtrack(int openN, int closedN, int n, List<String> res, StringBuilder stack) {
        if (openN == closedN && openN == n) {
            res.add(stack.toString());
            return;
        }

        if (openN < n) {
            stack.append('(');
            backtrack(openN + 1, closedN, n, res, stack);
            stack.deleteCharAt(stack.length() - 1);
        }
        if (closedN < openN) {
            stack.append(')');
            backtrack(openN, closedN + 1, n, res, stack);
            stack.deleteCharAt(stack.length() - 1);
        }
    }

    public List<String> generateParenthesis(int n) {
        List<String> res = new ArrayList<>();
        StringBuilder stack = new StringBuilder();
        backtrack(0, 0, n, res, stack);
        return res;
    }
}

class Solution {
    private val res = mutableListOf<List<Int>>()

    fun permute(nums: IntArray): List<List<Int>> {
        backtrack(mutableListOf(), nums, 0)
        return res
    }

    private fun backtrack(perm: MutableList<Int>, nums: IntArray, mask: Int) {
        if (perm.size == nums.size) {
            res.add(ArrayList(perm))
            return
        }
        for (i in nums.indices) {
            if (mask and (1 shl i) == 0) {
                perm.add(nums[i])
                backtrack(perm, nums, mask or (1 shl i))
                perm.removeAt(perm.size - 1)
            }
        }
    }
}

class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        self.res = []
        self.backtrack([], nums, [False] * len(nums))
        return self.res

    def backtrack(self, perm: List[int], nums: List[int], pick: List[bool]):
        if len(perm) == len(nums):
            self.res.append(perm[:])
            return
        for i in range(len(nums)):
            if not pick[i]:
                perm.append(nums[i])
                pick[i] = True
                self.backtrack(perm, nums, pick)
                perm.pop()
                pick[i] = False

