class Solution {
    func jump(_ nums: [Int]) -> Int {
        func dfs(_ i: Int) -> Int {
            if i == nums.count - 1 {
                return 0
            }
            if nums[i] == 0 {
                return 1000000
            }

            let end = min(nums.count - 1, i + nums[i])
            var res = 1000000
            for j in i + 1..<(end + 1) {
                res = min(res, 1 + dfs(j))
            }

            return res
        }

        return dfs(0)
    }
}

