class Solution {
    func permute(_ nums: [Int]) -> [[Int]] {
        var res = [[Int]]()

        func backtrack(_ perm: inout [Int], _ mask: Int) {
            if perm.count == nums.count {
                res.append(perm)
                return
            }
            for i in 0..<nums.count {
                if mask & (1 << i) == 0 {
                    perm.append(nums[i])
                    backtrack(&perm, mask | (1 << i))
                    perm.popLast()
                }
            }
        }

        var perm = [Int]()
        backtrack(&perm, 0)
        return res
    }
}

